create table if not exists memory_facts (id uuid primary key default gen_random_uuid(), scope text not null check (scope in ('agent','brand','global')), scope_id uuid, tier text not null check (tier in ('profile','log','note')), text text not null, source_type text, source_id uuid, learned_at timestamptz default now(), last_used_at timestamptz, active boolean default true);
create index if not exists memory_facts_scope_idx on memory_facts(scope, scope_id, tier);
create table if not exists agent_messages (id uuid primary key default gen_random_uuid(), from_agent_id uuid references agents(id), to_agent_id uuid references agents(id), run_id uuid references runs(id), packet jsonb not null, priority boolean default false, status text not null default 'queued' check (status in ('queued','delivered','consumed','failed')), created_at timestamptz default now(), delivered_at timestamptz);
create unique index if not exists agent_messages_delivery_once_idx on agent_messages(id) where status in ('delivered','consumed');
create table if not exists runs_lanes (id uuid primary key default gen_random_uuid(), run_id uuid references runs(id), agent_id uuid references agents(id), lane text not null check (lane in ('user','agent','automation','background')), status text not null default 'queued' check (status in ('queued','running','paused','done','failed','cancelled')), interrupt_reason text, started_at timestamptz, ended_at timestamptz, created_at timestamptz default now());
create table if not exists approval_requests (id uuid primary key default gen_random_uuid(), run_id uuid references runs(id), agent_id uuid references agents(id), action text not null, target text, detail jsonb, resolution text check (resolution in ('allow_once','deny','always','never','expired')), expires_at timestamptz, resolved_at timestamptz, created_at timestamptz default now());
create table if not exists audit_log (id uuid primary key default gen_random_uuid(), agent_id uuid references agents(id), run_id uuid references runs(id), action text not null, target text, decision text, detail jsonb, created_at timestamptz default now());
create table if not exists learning_proposals (id uuid primary key default gen_random_uuid(), agent_id uuid references agents(id), run_id uuid references runs(id), kind text, target_id uuid, description text not null, proposed_change jsonb not null, status text not null default 'pending' check (status in ('pending','approved','rejected')), created_at timestamptz default now(), reviewed_at timestamptz);
alter table memory_facts enable row level security; alter table agent_messages enable row level security; alter table runs_lanes enable row level security; alter table approval_requests enable row level security; alter table audit_log enable row level security; alter table learning_proposals enable row level security;
create policy "single_user_runtime_memory" on memory_facts for all using (true) with check (true); create policy "single_user_runtime_messages" on agent_messages for all using (true) with check (true); create policy "single_user_runtime_lanes" on runs_lanes for all using (true) with check (true); create policy "single_user_runtime_approvals" on approval_requests for all using (true) with check (true); create policy "single_user_runtime_audit" on audit_log for all using (true) with check (true); create policy "single_user_runtime_learning" on learning_proposals for all using (true) with check (true);
